        for (int i = 0; i < n; ++i) {
            primesOf[i] = factorDistinctPrimes(a[i]);
            for (int p : primesOf[i]) {
                auto it = cnt.find(p);
                if (it == cnt.end()) {
                    cnt.emplace(p, 1);
                    used.push_back(p);
